@startuml

class Customer {
  + address : string
  + vatNumber : string
  + headOfficeAddress : string
}

class Product {
  + name : string
  + stockLevel : int
}

class Order {
  + orderDate : date
  + paidDate : date
  + shippedDate : date
}

class OrderLine {
  + quantity : int
}

class Invoice {
  + invoiceDate : date
}

class Warehouse {
  + address : string
}

class Shipment {
  + status : string
}

class ShipmentLine {
  + status : string
}

class Delivery {
  + status : string
}

Customer "1" -- "*" Order : places
Customer "1" -- "*" Invoice : receives
Order "1" *-- "1..*" OrderLine : contains
OrderLine "*" -- "1" Product : refers to
Order "1" -- "0..*" Invoice : generates
Order "1" -- "0..*" Shipment : is split into
Shipment "1" *-- "1..*" ShipmentLine : contains
ShipmentLine "*" -- "1" OrderLine : fulfills
Shipment "1" -- "0..1" Delivery : results in
Warehouse "*" -- "*" Product : stores
Warehouse "*" -- "*" Customer : delivers to

@enduml

